2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
