1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType = DocType | 'in-rev' | 'out-rev' | 'transfer-rev';
17	
18	interface LedgerEntry {
19	  seq: number; // 全局流水序号，即提交顺序
20	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
21	  type: EntryType;
22	  product: string;
23	  wh: string; // 本流水条目变动余量的仓库
24	  qty: number; // 恒为正数，方向由类型 / 出入仓决定
25	  before: number;
26	  after: number;
27	  from?: string; // 调拨（或冲销调拨）的调出仓
28	  to?: string; // 调拨（或冲销调拨）的调入仓
29	  orig?: string; // 冲销流水：被冲销的原单编号
30	}
31	
32	interface DocRecord {
33	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
34	  resultLines: string[]; // 原提交结果，供幂等重放
35	}
36	
37	interface ReversalRecord {
38	  orig: string; // 被冲销的原单编号
39	  resultLines: string[]; // 冲销提交结果，供幂等重放
40	}
41	
42	interface Store {
43	  version: 1;
44	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
45	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
46	  entries: LedgerEntry[];
47	  docs: Record<string, DocRecord>; // 入库/出库/调拨单去重与结果
48	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果
49	}
50	
51	function nullProto<T extends object>(): T {
52	  return Object.create(null) as T;
53	}
54	
55	function emptyStore(): Store {
56	  return {
57	    version: 1,
58	    products: nullProto(),
59	    stock: nullProto(),
60	    entries: [],
61	    docs: nullProto(),
62	    reversals: nullProto(),
63	  };
64	}
65	
66	// ---------- 工具 ----------
67	
68	function isPlainObject(v: unknown): v is Record<string, unknown> {
69	  return typeof v === 'object' && v !== null && !Array.isArray(v);
70	}
71	
72	function isNonNegSafeInt(v: unknown): v is number {
73	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
74	}
75	
76	function isPosSafeInt(v: unknown): v is number {
77	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
78	}
79	
80	function trimOrThrow(label: string, raw: string): string {
81	  const s = raw.trim();
82	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
83	  return s;
84	}
85	
86	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
87	function stableStringify(v: unknown): string {
88	  if (isPlainObject(v)) {
89	    return (
90	      '{' +
91	      Object.keys(v)
92	        .sort()
93	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
94	        .join(',') +
95	      '}'
96	    );
97	  }
98	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
99	  return JSON.stringify(v);
100	}
101	
102	// ---------- 数据持久化 ----------
103	
104	function dataPath(dataDir: string): string {
105	  return join(dataDir, DATA_FILENAME);
106	}
107	
108	function loadStore(dataDir: string): Store {
109	  let raw: string;
110	  try {
111	    raw = readFileSync(dataPath(dataDir), 'utf8');
112	  } catch (e) {
113	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
114	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
115	  }
116	
117	  let data: unknown;
118	  try {
119	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
120	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
121	    data = JSON.parse(raw);
122	  } catch {
123	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
124	  }
125	  return validateStore(data);
126	}
127	
128	function validateStore(data: unknown): Store {
129	  const bad = (msg: string): DataError =>
130	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
131	
132	  if (!isPlainObject(data)) throw bad('根节点不是对象');
133	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
134	
135	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
136	  const store = emptyStore();
137	
138	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
139	  for (const [id, name] of Object.entries(data.products)) {
140	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
141	      throw bad('products 中存在非法编号或名称');
142	    store.products[id] = name;
143	  }
144	
145	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
146	  for (const [pid, whs] of Object.entries(data.stock)) {
147	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
148	    const whMap = nullProto<Record<string, number>>();
149	    for (const [wh, qty] of Object.entries(whs)) {
150	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
151	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
152	      whMap[wh] = qty;
153	    }
154	    store.stock[pid] = whMap;
155	  }
156	
157	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
158	  let lastSeq = 0;
159	  for (const e of data.entries as unknown[]) {
160	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
161	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
162	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
163	    const isRev = e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev';
164	    const isOrig = e.type === 'in' || e.type === 'out' || e.type === 'transfer';
165	    if (!isRev && !isOrig) throw bad('流水类型非法');
166	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
167	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
168	    if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
169	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
170	    if (e.type === 'transfer' || e.type === 'transfer-rev') {
171	      if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
172	        throw bad('调拨流水缺少调出/调入仓');
173	    }
174	    if (isRev) {
175	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
176	    } else if (e.orig !== undefined) {
177	      throw bad('原始单据流水不应携带冲销标记');
178	    }
179	    store.entries.push(e as unknown as LedgerEntry);
180	  }
181	
182	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
183	  for (const [docId, rec] of Object.entries(data.docs)) {
184	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
185	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
186	      throw bad(`单据 ${docId} 的去重记录非法`);
187	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
188	    const c = rec.content;
189	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer')
190	      throw bad(`单据 ${docId} 的业务类型非法`);
191	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
192	    for (const [pid, qty] of Object.entries(c.items)) {
193	      if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`单据 ${docId} 存在非法明细`);
194	    }
195	    if (c.type === 'transfer') {
196	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
197	        throw bad(`单据 ${docId} 的调拨仓非法`);
198	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
199	      throw bad(`单据 ${docId} 的仓库非法`);
200	    }
201	    store.docs[docId] = rec as unknown as DocRecord;
202	  }
203	
204	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理
205	  if (data.reversals !== undefined) {
206	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
207	    for (const [revId, rec] of Object.entries(data.reversals)) {
208	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
209	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
210	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
211	        throw bad(`冲销单 ${revId} 的记录非法`);
212	      const origRec = store.docs[rec.orig];
213	      if (origRec === undefined) throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
214	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始单据编号冲突`);
215	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
216	    }
217	    // 每张原单最多被成功冲销一次
218	    const origSeen = nullProto<Record<string, string>>();
219	    for (const [revId, rec] of Object.entries(store.reversals)) {
220	      if (origSeen[rec.orig] !== undefined)
221	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
222	      origSeen[rec.orig] = revId;
223	    }
224	    // 冲销流水必须能找到所属冲销单
225	    for (const e of store.entries) {
226	      if ((e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev') &&
227	          store.reversals[e.doc] === undefined)
228	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
229	    }
230	  }
231	
232	  return store;
233	}
234	
235	function saveStore(dataDir: string, store: Store): void {
236	  const path = dataPath(dataDir);
237	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
238	  try {
239	    mkdirSync(dataDir, { recursive: true });
240	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
241	    renameSync(tmp, path);
242	  } catch (e) {
243	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
244	  }
245	}
246	
247	// ---------- 参数解析 ----------
248	
249	interface ParsedArgs {
250	  positionals: string[];
251	  flags: Record<string, string>;
252	  multi: Record<string, string[]>;
253	}
254	
255	function parseArgs(
256	  tokens: string[],
257	  singles: string[],
258	  multis: string[] = [],
259	): ParsedArgs {
260	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
261	  const singleSet = new Set(singles);
262	  const multiSet = new Set(multis);
263	
264	  for (let i = 0; i < tokens.length; i++) {
265	    const tok = tokens[i];
266	    if (tok.startsWith('--')) {
267	      let key = tok;
268	      let value: string | undefined;
269	      const eq = tok.indexOf('=');
270	      if (eq >= 0) {
271	        key = tok.slice(0, eq);
272	        value = tok.slice(eq + 1);
273	      }
274	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
275	      if (value === undefined) {
276	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
277	        value = tokens[++i];
278	      }
279	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
280	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
281	      else out.flags[key] = value;
282	    } else {
283	      out.positionals.push(tok);
284	    }
285	  }
286	  return out;
287	}
288	
289	function parseItem(raw: string, merged: Map<string, number>): void {
290	  const idx = raw.indexOf(':');
291	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
292	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
293	  const qtyRaw = raw.slice(idx + 1).trim();
294	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
295	  const qty = Number(qtyRaw);
296	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
297	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
298	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
299	  merged.set(pid, sum);
300	}
301	
302	interface DocRequest {
303	  type: DocType;
304	  docId: string;
305	  wh?: string;
306	  from?: string;
307	  to?: string;
308	  items: Map<string, number>;
309	}
310	
311	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
312	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
313	  const docId = args.positionals[0];
314	  if (docId === undefined || args.positionals.length !== 1)
315	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
316	
317	  const items = new Map<string, number>();
318	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
319	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
320	
321	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
322	  if (type === 'transfer') {
323	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
324	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
325	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
326	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
327	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
328	  } else {
329	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
330	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
331	  }
332	  return req;
333	}
334	
335	// ---------- 业务核心 ----------
336	
337	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
338	
339	function canonicalContent(req: DocRequest): Record<string, unknown> {
340	  const items: Record<string, number> = nullProto();
341	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
342	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
343	  return { type: req.type, wh: req.wh!, items };
344	}
345	
346	function getStock(stock: Store['stock'], pid: string, wh: string): number {
347	  return stock[pid]?.[wh] ?? 0;
348	}
349	
350	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
351	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
352	}
353	
354	/**
355	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
356	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
357	 */
358	function cloneStock(stock: Store['stock']): Store['stock'] {
359	  const out = nullProto<Store['stock']>();
360	  for (const pid of Object.keys(stock)) {
361	    const whMap = nullProto<Record<string, number>>();
362	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
363	    out[pid] = whMap;
364	  }
365	  return out;
366	}
367	
368	interface SubmitOutcome {
369	  duplicate: boolean;
370	  lines: string[];
371	}
372	
373	/** 整单先校验、模拟，全部合法后才一次性落库；任一明细失败则全部保持原状。 */
374	function submitDocument(dataDir: string, store: Store, req: DocRequest): SubmitOutcome {
375	  const content = canonicalContent(req);
376	  const existed = store.docs[req.docId];
377	  if (existed !== undefined) {
378	    if (stableStringify(existed.content) !== stableStringify(content))
379	      throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
380	    return { duplicate: true, lines: existed.resultLines }; // 幂等：返回原结果，不动库存
381	  }
382	  // 编号空间与出库/入库/调拨/冲销单共用
383	  if (store.reversals[req.docId] !== undefined)
384	    throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
385	
386	  for (const pid of req.items.keys()) {
387	    if (store.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
388	  }
389	
390	  const draft: Store['stock'] = cloneStock(store.stock);
391	  const additions: LedgerEntry[] = [];
392	  const reportLines: string[] = [];
393	  let seq = store.entries.length;
394	  const typeLabel = req.type === 'in' ? '入库' : req.type === 'out' ? '出库' : '调拨';
395	
396	  for (const pid of [...req.items.keys()].sort()) {
397	    const qty = req.items.get(pid)!;
398	
399	    if (req.type === 'in') {
400	      const wh = req.wh!;
401	      const before = getStock(draft, pid, wh);
402	      const after = before + qty;
403	      if (after > MAX_SAFE) throw new BizError(`商品 ${pid} 入库后余量超出安全整数范围，拒绝整单`);
404	      setStock(draft, pid, wh, after);
405	      additions.push({ seq: ++seq, doc: req.docId, type: 'in', product: pid, wh, qty, before, after });
406	      reportLines.push(`入库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
407	    } else if (req.type === 'out') {
408	      const wh = req.wh!;
409	      const before = getStock(draft, pid, wh);
410	      if (before < qty)
411	        throw new BizError(`商品 ${pid} 仓库 ${wh} 余量不足（当前 ${before}，需出库 ${qty}），拒绝整单`);
412	      const after = before - qty;
413	      setStock(draft, pid, wh, after);
414	      additions.push({ seq: ++seq, doc: req.docId, type: 'out', product: pid, wh, qty, before, after });
415	      reportLines.push(`出库 ${pid} @${wh} -${qty}：${before} -> ${after}`);
416	    } else {
417	      const from = req.from!;
418	      const to = req.to!;
419	      const beforeFrom = getStock(draft, pid, from);
420	      if (beforeFrom < qty)
421	        throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
422	      const afterFrom = beforeFrom - qty;
423	      const beforeTo = getStock(draft, pid, to);
424	      const afterTo = beforeTo + qty;
425	      if (afterTo > MAX_SAFE) throw new BizError(`商品 ${pid} 调入后余量超出安全整数范围，拒绝整单`);
426	      setStock(draft, pid, from, afterFrom);
427	      setStock(draft, pid, to, afterTo);
428	      additions.push({
429	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: from,
430	        qty, before: beforeFrom, after: afterFrom, from, to,
431	      });
432	      additions.push({
433	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
434	        qty, before: beforeTo, after: afterTo, from, to,
435	      });
436	      reportLines.push(
437	        `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
438	      );
439	    }
440	  }
441	
442	  // 全部明细合法：一次性提交并在保存成功后才算成功
443	  store.stock = draft;
444	  store.entries.push(...additions);
445	  store.docs[req.docId] = { content, resultLines: reportLines };
446	  saveStore(dataDir, store);
447	
448	  return {
449	    duplicate: false,
450	    lines: [`${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`, ...reportLines],
451	  };
452	}
453	
454	/**
455	 * 整单冲销：在“当前余量”上应用原单的相反变动（不回滚历史、不恢复绝对余量）。
456	 * 任一商品扣回不足或补回后溢出，则整单拒绝、不留任何痕迹；成功后库存/流水/冲销
457	 * 关系/结果一起原子保存。
458	 */
459	function submitReversal(dataDir: string, store: Store, revId: string, origId: string): SubmitOutcome {
460	  const existed = store.reversals[revId];
461	  if (existed !== undefined) {
462	    if (existed.orig !== origId)
463	      throw new BizError(
464	        `冲销单编号 ${revId} 已用于冲销原单 ${existed.orig}，不能改冲原单 ${origId}，拒绝提交`,
465	      );
466	    return { duplicate: true, lines: existed.resultLines }; // 幂等重放：返回原冲销结果，不再变动
467	  }
468	  // 冲销单与入库/出库/调拨共用唯一编号空间
469	  if (store.docs[revId] !== undefined)
470	    throw new BizError(`编号 ${revId} 已是入库/出库/调拨单编号，不能用作冲销单，拒绝提交`);
471	
472	  // 只能冲销成功的原始库存单据：不存在的原单、冲销单本身均不可冲销
473	  const origRec = store.docs[origId];
474	  if (origRec === undefined)
475	    throw new BizError(`原单 ${origId} 不存在或不是成功的原始库存单据，拒绝冲销`);
476	
477	  for (const [existingRev, rec] of Object.entries(store.reversals)) {
478	    if (rec.orig === origId)
479	      throw new BizError(`原单 ${origId} 已被冲销单 ${existingRev} 成功冲销，每张原单只能冲销一次`);
480	  }
481	
482	  const c = origRec.content;
483	  const type = c.type as DocType;
484	  const items = c.items as Record<string, number>;
485	  const pids = Object.keys(items).sort();
486	
487	  const draft: Store['stock'] = cloneStock(store.stock);
488	  const additions: LedgerEntry[] = [];
489	  const reportLines: string[] = [];
490	  let seq = store.entries.length;
491	  const typeLabel = type === 'in' ? '入库' : type === 'out' ? '出库' : '调拨';
492	  const revType = type === 'in' ? 'in-rev' : type === 'out' ? 'out-rev' : 'transfer-rev';
493	
494	  for (const pid of pids) {
495	    const qty = items[pid]; // 原单同商品合并后的数量
496	
497	    if (type === 'in') {
498	      // 冲销入库：从原目标仓扣回
499	      const wh = c.wh as string;
500	      const before = getStock(draft, pid, wh);
501	      if (before < qty)
502	        throw new BizError(
503	          `冲销入库原单 ${origId}：商品 ${pid} 仓库 ${wh} 当前余量 ${before} 不足扣回 ${qty}，拒绝整单`,
504	        );
505	      const after = before - qty;
506	      setStock(draft, pid, wh, after);
507	      additions.push({
508	        seq: ++seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
509	      });
510	      reportLines.push(`冲销入库 原单=${origId} 商品=${pid} @${wh} -${qty}：${before} -> ${after}`);
511	    } else if (type === 'out') {
512	      // 冲销出库：向原来源仓补回
513	      const wh = c.wh as string;
514	      const before = getStock(draft, pid, wh);
515	      const after = before + qty;
516	      if (after > MAX_SAFE)
517	        throw new BizError(
518	          `冲销出库原单 ${origId}：商品 ${pid} 仓库 ${wh} 补回后余量超出安全整数范围，拒绝整单`,
519	        );
520	      setStock(draft, pid, wh, after);
521	      additions.push({
522	        seq: ++seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
523	      });
524	      reportLines.push(`冲销出库 原单=${origId} 商品=${pid} @${wh} +${qty}：${before} -> ${after}`);
525	    } else {
526	      // 冲销调拨：从原调入仓扣回，向原调出仓补回
527	      const from = c.from as string;
528	      const to = c.to as string;
529	      const beforeTo = getStock(draft, pid, to);
530	      if (beforeTo < qty)
531	        throw new BizError(
532	          `冲销调拨原单 ${origId}：商品 ${pid} 原调入仓 ${to} 当前余量 ${beforeTo} 不足扣回 ${qty}，拒绝整单`,
533	        );
534	      const afterTo = beforeTo - qty;
535	      const beforeFrom = getStock(draft, pid, from);
536	      const afterFrom = beforeFrom + qty;
537	      if (afterFrom > MAX_SAFE)
538	        throw new BizError(
539	          `冲销调拨原单 ${origId}：商品 ${pid} 原调出仓 ${from} 补回后余量超出安全整数范围，拒绝整单`,
540	        );
541	      setStock(draft, pid, to, afterTo);
542	      setStock(draft, pid, from, afterFrom);
543	      additions.push({
544	        seq: ++seq, doc: revId, type: revType, product: pid, wh: to,
545	        qty, before: beforeTo, after: afterTo, from, to, orig: origId,
546	      });
547	      additions.push({
548	        seq: ++seq, doc: revId, type: revType, product: pid, wh: from,
549	        qty, before: beforeFrom, after: afterFrom, from, to, orig: origId,
550	      });
551	      reportLines.push(
552	        `冲销调拨 原单=${origId} 商品=${pid} ${to} -> ${from} ${qty}：` +
553	          `${to} ${beforeTo}->${afterTo}；${from} ${beforeFrom}->${afterFrom}`,
554	      );
555	    }
556	  }
557	
558	  // 全部明细合法：库存、流水、冲销关系、结果一次性提交，保存成功才算成功
559	  store.stock = draft;
560	  store.entries.push(...additions);
561	  store.reversals[revId] = { orig: origId, resultLines: reportLines };
562	  saveStore(dataDir, store);
563	
564	  return {
565	    duplicate: false,
566	    lines: [
567	      `冲销单 ${revId} 提交成功，冲销${typeLabel}原单 ${origId}，共 ${pids.length} 种商品：`,
568	      ...reportLines,
569	    ],
570	  };
571	}
572	
573	// ---------- 各命令处理 ----------
574	
575	function runProduct(rest: string[], dataDir: string, store: Store): void {
576	  const sub = rest[0];
577	  const tokens = rest.slice(1);
578	  if (sub === 'add') {
579	    const args = parseArgs(tokens, []);
580	    const [idRaw, nameRaw, ...extra] = args.positionals;
581	    if (idRaw === undefined || nameRaw === undefined || extra.length > 0)
582	      throw new UsageError('用法：product add <商品编号> <商品名称>');
583	    const id = trimOrThrow('商品编号', idRaw);
584	    const name = trimOrThrow('商品名称', nameRaw);
585	    if (store.products[id] !== undefined)
586	      throw new BizError(`商品编号 ${id} 已存在（${store.products[id]}），拒绝重复登记且不覆盖原资料`);
587	    store.products[id] = name;
588	    saveStore(dataDir, store);
589	    console.log(`已登记商品：${id}\t${name}`);
590	  } else if (sub === 'list' || sub === 'ls') {
591	    const args = parseArgs(tokens, []);
592	    if (args.positionals.length > 0) throw new UsageError('用法：product list');
593	    const ids = Object.keys(store.products).sort();
594	    console.log(`已登记商品（${ids.length}）：`);
595	    if (ids.length === 0) {
596	      console.log('（暂无已登记商品）');
597	    } else {
598	      console.log('编号\t名称');
599	      for (const id of ids) console.log(`${id}\t${store.products[id]}`);
600	    }
601	  } else {
602	    throw new UsageError(sub === undefined ? '用法：product <add|list> …' : `未知 product 子命令：${sub}`);
603	  }
604	}
605	
606	function runBalance(rest: string[], store: Store): void {
607	  const args = parseArgs(rest, ['--wh']);
608	  const [pidRaw, ...extra] = args.positionals;
609	  if (pidRaw === undefined || extra.length > 0) throw new UsageError('用法：balance <商品编号> [--wh <仓库>]');
610	  const pid = trimOrThrow('商品编号', pidRaw);
611	
612	  if (args.flags['--wh'] !== undefined) {
613	    const wh = trimOrThrow('仓库标识', args.flags['--wh']);
614	    const qty = getStock(store.stock, pid, wh); // 未发生变动的组合余量为 0
615	    console.log(`余量：商品 ${pid} 仓库 ${wh} = ${qty}`);
616	    return;
617	  }
618	
619	  const map = store.stock[pid] ?? {};
620	  const whs = Object.keys(map).filter((w) => map[w] !== 0).sort();
621	  if (whs.length === 0) {
622	    console.log(`商品 ${pid} 在各仓库余量均为 0`);
623	    return;
624	  }
625	  console.log(`商品 ${pid} 各仓余量：`);
626	  let total = 0;
627	  for (const wh of whs) {
628	    console.log(`仓库 ${wh}：${map[wh]}`);
629	    total += map[wh];
630	  }
631	  console.log(`合计：${total}`);
632	}
633	
634	const TYPE_LABEL: Record<EntryType, string> = {
635	  in: '入库',
636	  out: '出库',
637	  transfer: '调拨',
638	  'in-rev': '冲销入库',
639	  'out-rev': '冲销出库',
640	  'transfer-rev': '冲销调拨',
641	};
642	
643	function formatEntry(e: LedgerEntry): string {
644	  let signed: string;
645	  if (e.type === 'in') signed = `+${e.qty}`;
646	  else if (e.type === 'out') signed = `-${e.qty}`;
647	  else signed = `${e.wh === e.to ? '+' : '-'}${e.qty}`;
648	  let line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
649	  if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
650	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
651	  return line;
652	}
653	
654	function runFlow(rest: string[], store: Store): void {
655	  const args = parseArgs(rest, ['--product', '--wh']);
656	  if (args.positionals.length > 0) throw new UsageError('用法：flow (--product <商品编号> | --wh <仓库>)…');
657	  const product = args.flags['--product'];
658	  const wh = args.flags['--wh'];
659	  if (product === undefined && wh === undefined)
660	    throw new UsageError('flow 至少需要一个过滤条件：--product <商品编号> 和/或 --wh <仓库>');
661	  const pid = product === undefined ? undefined : trimOrThrow('商品编号', product);
662	  const wid = wh === undefined ? undefined : trimOrThrow('仓库标识', wh);
663	
664	  const rows = store.entries.filter(
665	    (e) => (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid),
666	  );
667	  const scope = [pid !== undefined ? `商品=${pid}` : null, wid !== undefined ? `仓库=${wid}` : null]
668	    .filter(Boolean)
669	    .join(' ');
670	  console.log(`流水（${scope}），共 ${rows.length} 条，按提交顺序（冲销流水标注原单编号）：`);
671	  if (rows.length === 0) console.log('（无匹配流水）');
672	  else for (const e of rows) console.log(formatEntry(e));
673	
674	  // 附：范围内原始单据的冲销状态
675	  const origDocs = new Set(rows.filter((e) => e.orig === undefined).map((e) => e.doc));
676	  const status: string[] = [];
677	  for (const docId of [...origDocs].sort()) {
678	    for (const [revId, rec] of Object.entries(store.reversals)) {
679	      if (rec.orig === docId) status.push(`原单 ${docId} 已由冲销单 ${revId} 冲销`);
680	    }
681	  }
682	  for (const line of status) console.log(line);
683	}
684	
685	function runReverse(rest: string[], dataDir: string, store: Store): void {
686	  const args = parseArgs(rest, ['--orig']);
687	  const revRaw = args.positionals[0];
688	  if (revRaw === undefined || args.positionals.length !== 1)
689	    throw new UsageError('用法：reverse <冲销单编号> --orig <原单编号>');
690	  if (args.flags['--orig'] === undefined)
691	    throw new UsageError('冲销必须通过 --orig <原单编号> 指定被冲销的原单');
692	  const revId = trimOrThrow('冲销单编号', revRaw);
693	  const origId = trimOrThrow('原单编号', args.flags['--orig']);
694	  const outcome = submitReversal(dataDir, store, revId, origId);
695	  if (outcome.duplicate) {
696	    console.log(
697	      `冲销单 ${revId} 为重复提交，原单为 ${origId}，返回原冲销结果（库存与流水不再变动）：`,
698	    );
699	  }
700	  for (const line of outcome.lines) console.log(line);
701	}
702	
703	// ---------- 帮助与入口 ----------
704	
705	const HELP = `${APP_NAME} —— 本地多仓库存台账
706	
707	用法：
708	  node app.ts [-d, --data <数据目录>] <命令> [参数]
709	
710	全局选项：
711	  -d, --data <目录>   数据目录（默认 ./.stockroom）；不同目录的数据互不影响
712	
713	命令：
714	  product add <编号> <名称>                 登记商品（编号唯一、区分大小写，去空白后不能为空）
715	  product list                              列出已登记商品
716	  in <单据编号> --wh <仓库> --item <编号:数量> [...]       入库
717	  out <单据编号> --wh <仓库> --item <编号:数量> [...]      出库（余量不足整单拒绝）
718	  transfer <单据编号> --from <源仓> --to <目标仓> \\
719	           --item <编号:数量> [...]                        跨仓调拨（两仓不能相同）
720	  reverse <冲销单编号> --orig <原单编号>     整单冲销已成功的入库/出库/调拨单
721	  balance <商品编号> [--wh <仓库>]           查询余量；省略 --wh 查询各仓
722	  flow --product <编号> [--wh <仓库>]        按商品/仓库查询流水（至少一个过滤条件）
723	       | --wh <仓库> [--product <编号>]
724	  -h, --help                                显示本帮助
725	
726	规则：
727	  数量必须为正安全整数；同单同商品的重复明细先合并，再做足量与溢出校验；
728	  任一明细不合法则整单拒绝。单据编号（含冲销单）在同一数据目录内共用全局唯一
729	  编号空间，相同内容重复提交返回原结果且不重复变动，同编号不同内容拒绝；失败
730	  提交不占用编号。
731	
732	冲销规则：
733	  冲销在“当前余量”上应用原单的相反变动，不回滚原单之后的其他业务、不恢复绝对
734	  余量：冲销入库从原目标仓扣回；冲销出库向原来源仓补回；冲销调拨从原调入仓扣
735	  回并向原调出仓补回。数量取原单合并后的明细。任一商品扣回不足或补回后溢出则
736	  整单拒绝、不占用冲销单编号、原单不标记冲销，条件改善后可重试。
737	  只能冲销成功的原始单据；原单不存在、冲销单本身、已冲销过的原单均不能再次冲
738	  销，每张原单最多冲销一次。冲销成功后重放原单仍只返回其最初结果，不会重新生
739	  效；重放冲销单返回原冲销结果，不再变动，同编号改指其他原单则拒绝。
740	
741	示例：
742	  node app.ts -d ./data product add P1 螺丝
743	  node app.ts -d ./data in D1 --wh W1 --item P1:10 --item P2:3
744	  node app.ts -d ./data out D2 --wh W1 --item P1:4
745	  node app.ts -d ./data transfer D3 --from W1 --to W2 --item P1:2 --item P1:3
746	  node app.ts -d ./data reverse R1 --orig D3
747	  node app.ts -d ./data balance P1
748	  node app.ts -d ./data balance P1 --wh W1
749	  node app.ts -d ./data flow --product P1
750	  node app.ts -d ./data flow --wh W2`;
751	
752	function printHelp(): void {
753	  console.log(HELP);
754	}
755	
756	function run(argv: string[]): void {
757	  // 先抽出全局 -d/--data，其余按命令解析
758	  let dataDir = DEFAULT_DATA_DIR;
759	  const rest: string[] = [];
760	  for (let i = 0; i < argv.length; i++) {
761	    const t = argv[i];
762	    if (t === '-d' || t === '--data') {
763	      if (i + 1 >= argv.length) throw new UsageError(`参数 ${t} 缺少数据目录取值`);
764	      dataDir = argv[++i];
765	    } else if (t.startsWith('--data=')) {
766	      dataDir = t.slice('--data='.length);
767	    } else {
768	      rest.push(t);
769	    }
770	  }
771	
772	  if (rest.length === 0) {
773	    printHelp();
774	    return;
775	  }
776	  const cmd = rest[0];
777	  if ((cmd === '-h' || cmd === '--help') && rest.length === 1) {
778	    printHelp();
779	    return;
780	  }
781	
782	  const tokens = rest.slice(1);
783	  switch (cmd) {
784	    case 'product': {
785	      const store = loadStore(dataDir);
786	      runProduct(tokens, dataDir, store);
787	      break;
788	    }
789	    case 'in':
790	    case 'out':
791	    case 'transfer': {
792	      const req = parseDocArgs(cmd, tokens);
793	      const store = loadStore(dataDir);
794	      const outcome = submitDocument(dataDir, store, req);
795	      if (outcome.duplicate) {
796	        console.log(`单据 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
797	      }
798	      for (const line of outcome.lines) console.log(line);
799	      break;
800	    }
801	    case 'reverse': {
802	      const store = loadStore(dataDir);
803	      runReverse(tokens, dataDir, store);
804	      break;
805	    }
806	    case 'balance': {
807	      const store = loadStore(dataDir);
808	      runBalance(tokens, store);
809	      break;
810	    }
811	    case 'flow': {
812	      const store = loadStore(dataDir);
813	      runFlow(tokens, store);
814	      break;
815	    }
816	    default:
817	      throw new UsageError(`未知命令：${cmd}（使用 --help 查看可用命令）`);
818	  }
819	}
820	
821	try {
822	  run(process.argv.slice(2));
823	} catch (e) {
824	  if (e instanceof UsageError) {
825	    console.error(`${APP_NAME}: ${e.message}`);
826	    process.exit(2);
827	  }
828	  if (e instanceof BizError || e instanceof DataError) {
829	    console.error(`${APP_NAME}: ${e.message}`);
830	    process.exit(1);
831	  }
832	  console.error(`${APP_NAME}: 发生未预期错误：${(e as Error)?.stack ?? String(e)}`);
833	  process.exit(1);
834	}
